onClick:
{{
  (function() {
    // 1. Trova il medico usando i campi della tua SELECT
    const medico = GetMedics.data.find(u => u.RSMEDICID == Select1.selectedOptionValue);

    if (!medico) {
      showAlert("Selezionare un medico", "warning");
      return;
    }

    const oggi = moment();
    const domani = moment().add(1, 'days').startOf('day');
    const scadenzaAttuale = moment(medico.RSVALIDTO).startOf('day');

    // CONTROLLO 1: Già attivo
    if (scadenzaAttuale.isAfter(domani)) {
      showAlert("MEDICO GIÀ ATTIVO", "info");
      return;
    }

    // CONTROLLO 2: Scaduto da troppo tempo (> 15 gg)
    if (oggi.diff(scadenzaAttuale, 'days') > 15) {
      showAlert("⛔ BLOCCO: Scaduto da oltre 15 giorni.", "error");
      return;
    }

    // ESECUZIONE
    Update_BA_MEDIC.run()
      .then(() => Update_STRUCTURE.run())
      .then(() => {
        // COSTRUZIONE NOME: Usiamo RSLASTNAME e RSFIRSTNAME come da tua query GetMedics
        const nomeCompleto = (medico.RSLASTNAME || '').trim() + " " + (medico.RSFIRSTNAME || '').trim();

        return InviaEmailAccreditamento.run({
          nomeMedico: nomeCompleto,
          scadenzaVecchia: scadenzaAttuale.format('DD/MM/YYYY'),
          nuovaScadenza: domani.format('DD/MM/YYYY')
        });
      })
      .then(() => GetMedics.run())
      .then(() => showAlert("✅ Accreditamento completato e notifica inviata!", "success"))
      .catch((err) => showAlert("Errore: " + err.message, "error"));
  })()
}}
